from __future__ import annotations

import base64
import hashlib
import zlib
from functools import lru_cache

SDPOSE_EMPTY_PROMPT_SHA256 = "168b6113df66f4f1006e36bcd143aa46215a28ff60d0e769cc8a412c16c0b951"
_SOURCE_COMMIT = "14b05228cef127ce529bc0c08660770d4af3e9a8"
_COMPRESSED_BASE64 = """

"""


@lru_cache(maxsize=1)
def _raw_empty_prompt() -> bytes:
    encoded = "".join(_COMPRESSED_BASE64.split())
    try:
        raw = zlib.decompress(base64.b64decode(encoded, validate=True))
    except (ValueError, zlib.error) as exc:
        raise RuntimeError("invalid packaged SDPose empty-prompt tensor") from exc
    if len(raw) != 4096 or hashlib.sha256(raw).hexdigest() != SDPOSE_EMPTY_PROMPT_SHA256:
        raise RuntimeError("packaged SDPose empty-prompt digest mismatch")
    return raw


def sdpose_empty_prompt():
    import torch

    return torch.frombuffer(bytearray(_raw_empty_prompt()), dtype=torch.float16).reshape(1, 2, 1024)


def sdpose_empty_prompt_provenance() -> dict[str, object]:
    return {
        "source_commit": _SOURCE_COMMIT,
        "source_path": "comfy_extras/nodes_lotus.py",
        "source_repo": "https://github.com/Comfy-Org/ComfyUI",
        "tensor_dtype": "float16-le",
        "tensor_sha256": SDPOSE_EMPTY_PROMPT_SHA256,
        "tensor_shape": [1, 2, 1024],
    }


__all__ = [
    "SDPOSE_EMPTY_PROMPT_SHA256",
    "sdpose_empty_prompt",
    "sdpose_empty_prompt_provenance",
]
